import * as fs from "node:fs";
import * as os from "node:os";
function main(): void {
  const dir = fs.mkdtempSync(os.tmpdir() + "/nd8-");
  console.log(dir.length - (os.tmpdir() + "/nd8-").length);
  const a = dir + "/a";
  const b = dir + "/b";
  fs.writeFileSync(a, "x");
  fs.copyFileSync(a, b, 0);
  try { fs.copyFileSync(a, b, fs.constants.COPYFILE_EXCL); } catch (e: any) { console.log(e.code); }
  const fd = fs.openSync(a, "r+");
  fs.fsyncSync(fd);
  fs.fdatasyncSync(fd);
  fs.closeSync(fd);
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  console.log(entries.sort((x, y) => x.name < y.name ? -1 : 1).map((e) => e.name));
  fs.rmSync(dir, { recursive: true });
}
